// src/services/api.js
const BASE_URL = '';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });
  if (!res.ok) {
    let msg = `Request failed: ${res.status}`;
    try { msg = (await res.json()).message || msg; } catch {}
    throw new Error(msg);
  }
  return res.json();
}

export function login(body) { return request('/auth/login', { method: 'POST', body: JSON.stringify(body) }); }
export function register(body) { return request('/auth/register', { method: 'POST', body: JSON.stringify(body) }); }
export function getQuestions() { return request('/questions'); }
export function getQuestionById(id) { return request(`/questions/${id}`); }
export function postQuestion(q) { return request('/questions', { method:'POST', body: JSON.stringify(q) }); }
export function getAnswersByQuestionId(id) { return request(`/answers/question/${id}`); }
export function postAnswer(qId, ans) { return request(`/questions/${qId}/answers`, { method:'POST', body: JSON.stringify(ans) }); }
